    (68, 'after', r'''ResolvedAgentTools 五字段：hasWildcard 是否全放行、validTools/invalidTools 是 spec 级账本（给 UI 报「你写的工具名不存在」）、resolvedTools 是去重后的 Tool 对象、allowedAgentTypes 是 Agent 工具 spec 里带的子代理白名单。'''),
    (85, 'after', r'''MCP 工具（mcp__ 前缀）对所有 agent 放行——agent 能用什么 MCP 服务器由 frontmatter 的 mcpServers 决定，不在这张静态禁表里。'''),
    (93, 'after', r'''plan 模式的 agent 放行 ExitPlanMode：进程内队友在计划模式下要能提交计划退出，这条优先级高于两张禁表。'''),
    (99, 'after', r'''自定义 agent（非 built-in）额外过 CUSTOM_AGENT_DISALLOWED_TOOLS——内置 agent 是官方审计过的面，自定义的不享受同等待遇。'''),
    (113, 'after', r'''异步 agent 白名单制：不在 ASYNC_AGENT_ALLOWED_TOOLS 里的一律禁。in-process 队友两个例外：AgentTool（允许 spawn 同步子代理，AgentTool.call() 里还有校验防后台 agent 互相 spawn）+ 任务工具（经共享任务列表协作）。'''),
    (116, 'after', r'''过滤顺序有讲究：MCP 特例 → plan 特例 → 全禁表 → 自定义禁表 → 异步白名单。先特例后禁表，ExitPlanMode 才能同时绕过 ALL 和 async 两张表。'''),
