    (357, 'after', r'''返回的 usage 直接取最后一条 assistant 消息的 usage（含整个会话累计的 cache token 账）。'''),
    (359, 'after', r'''getLastToolUseName：取 assistant 消息里最后一个 tool_use 块的名字——「当前正在跑什么工具」的实时描述源。'''),
    (367, 'after', r'''findLast（不是 find）：并行工具调用时要的是最后发起的那个。'''),
    (387, 'after', r'''emitTaskProgress：把 tracker 进度翻译成 SDK 进度事件；activityDescription 优先用 tracker 里的实时解析描述，取不到才用初始 description。'''),
    (403, 'after', r'''classifyHandoffIfNeeded：auto 模式下 subagent 交还控制权时跑一次分类器审查——这是 auto 模式「事后审」的点位，与事前的 canUseTool 分类互补。'''),
    (405, 'after', r'''双门控：feature 开着且 permissionMode 是 auto 才跑；其他模式父级自己审，不需要分类器。'''),
    (408, 'after', r'''transcript 建不出来（没有可回顾的工具）直接跳过——分类器无米下锅。'''),
    (424, 'after', r'''分类 prompt：subagent 已交还控制权，让分类器按块规则审查 subagent 的工作，发现危险文件告知主 agent（主 agent 会看到理由）。注意 user role 的消息是构造给分类器看的，不是真用户。'''),
    (430, 'after', r'''三态归一：unavailable（分类器本身不可用）/ blocked / allowed。'''),
    (459, 'after', r'''埋点字段极全：两阶段分类器的 requestId/msgId/stage 全带，isHandoff: true 区分普通工具分类；toolName 故意用 LEGACY_AGENT_TOOL_NAME——Task→Agent 改名后保分析连续性；agentMsgId 取 subagent 最后一条 assistant 消息（分类 transcript 里交接审查提示前的最后内容）。'''),
    (477, 'after', r'''shouldBlock 两种出口：分类器不可用→带警告放行（父级自行验证，fail-open 但留痕）；真 block→SECURITY WARNING 前缀拼进结果，父 agent 看到会先审查再动作。'''),
    (481, 'after', r'''默认返回 null：没警告，父级拿到的就是纯净结果。'''),
    (483, 'after', r'''extractPartialResult：异步 agent 被杀时保留它已完成的工作——从后往前找第一条有文本的 assistant 消息。'''),
    (500, 'after', r'''倒序扫描：最新的文本优先（被杀时最后想说的往往最重要）。'''),
    (507, 'after', r'''runAsyncAgentLifecycle：后台 agent 从 spawn 到终态通知的驱动器——AgentTool 的异步启动路径和 resumeAgentBackground 共用，保证两条入口行为一致。'''),
    (535, 'after', r'''签名即契约：makeStream 是注入的 agent 流工厂（onCacheSafeParams 回调从里面透出），getWorktreeResult 惰性取 worktree 信息（不隔离时是零开销空实现）。'''),
    (553, 'after', r'''onCacheSafeParams 仅在 enableSummarization 时构造：启动后台摘要（周期性 fork agent 对话生成进度摘要，吃 prompt cache），stop 句柄留着供结束时停。'''),
    (570, 'after', r'''retain 任务（UI 持有查看）立即把消息追加进 AppState。先写盘再 yield 保证 live 恒是 disk 的后缀，bootstrap 并行读盘按 UUID 合并前缀才顺序正确——这个不变式是消息不重不乱的关键。'''),
    (581, 'after', r'''进度双写：updateProgressFromMessage 更新本地 tracker（token/工具数/活动描述），updateAsyncAgentProgress 推 AppState 供 UI 渲染。'''),
    (593, 'after', r'''流结束：先停摘要，再 finalizeAgentTool 压结果。'''),
    (603, 'after', r'''completeAsyncAgent 先置完成态——TaskOutput(block=true) 立即解除阻塞。分类（API 调用）和 worktree（git exec）是通知装饰，可能 hang，绝不能门控状态转换（gh-20236 的教训）。'''),
    (620, 'after', r'''handoff 警告拼在最终消息最前面——父 agent 第一眼看到的是安全提示。'''),
    (637, 'after', r'''enqueueAgentNotification 完成通知：描述、最终消息、用量、toolUseId、worktree 结果一起进通知队列。'''),
    (669, 'after', r'''AbortError 分支（用户 kill）：killAsyncAgent 在 TaskStop 已置 killed 时是 no-op，但只有这个 catch 持有 agentMessages，通知必须无条件发；先转状态再清 worktree——git hang 也挡不住 TaskOutput 解锁（gh-20236）；extractPartialResult 保留部分工作，不让人白跑。'''),
    (681, 'after', r'''其他错误分支：failAsyncAgent 置 failed + 通知带 error 原文。'''),
    (685, 'after', r'''finally：清 invoked skills 和 dump 状态两个 agent 级缓存——不清会跨 agent 串味（下一个 agent 看到上一个的技能调用记录）。'''),
